INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2023/09/22 14:59:59", 126401, 1, "いらっしゃいませっ♪\nキャラバンコインを使って\n買い物ができますよっ！", 1, "クローチェ", -470.0, "2023/06/30 12:00:00", 1, 2002, 10001, 2, 1.47);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2023/09/22 14:59:59", 126401, 2, "素敵な品が揃ってるので\nたーっくさん買っていって\nくださいねっ♪", 2, "クローチェ", -470.0, "2023/06/30 12:00:00", 1, 2002, 10002, 1, 2.15);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2023/09/22 14:59:59", 126501, 1, "ショップへようこそ\nキャラバンコインはこちら\nで買い物に使えますよ", 2, "ライラエル", -470.0, "2023/06/30 12:00:00", 1, 2002, 10003, 2, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2023/09/22 14:59:59", 126501, 2, "こちらのショップで\n買い物をして、素敵な\n旅を楽しんでくださいね", 1, "ライラエル", -470.0, "2023/06/30 12:00:00", 1, 2002, 10004, 1, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2023/12/22 14:59:59", 127702, 1, "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", 2, "リンド", -470.0, "2023/09/15 15:00:00", 2, 2002, 10005, 2, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2023/12/22 14:59:59", 127702, 2, "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", 2, "リンド", -470.0, "2023/09/15 15:00:00", 2, 2002, 10006, 2, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2023/12/22 14:59:59", 127802, 1, "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", 1, "ヴルム", -470.0, "2023/09/15 15:00:00", 2, 2002, 10007, 1, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2023/12/22 14:59:59", 127802, 2, "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", 2, "ヴルム", -470.0, "2023/09/15 15:00:00", 2, 2002, 10008, 1, 6.5);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2024/03/22 14:59:59", 129602, 1, "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", 2, "アネモネ", -470.0, "2023/12/15 15:00:00", 3, 2002, 10009, 1, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2024/03/22 14:59:59", 129602, 2, "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", 2, "アネモネ", -470.0, "2023/12/15 15:00:00", 3, 2002, 10010, 1, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2024/03/22 14:59:59", 129701, 1, "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", 1, "ネフィ=ネラ", -470.0, "2023/12/15 15:00:00", 3, 2002, 10011, 1, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2024/03/22 14:59:59", 129701, 2, "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", 2, "ネフィ=ネラ", -470.0, "2023/12/15 15:00:00", 3, 2002, 10012, 1, 6.2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2024/06/22 14:59:59", 130301, 1, "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", 3, "カノン", -470.0, "2024/03/15 15:00:00", 4, 2002, 10013, 5, 3.1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2024/06/22 14:59:59", 130301, 2, "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", 3, "カノン", -470.0, "2024/03/15 15:00:00", 4, 2002, 10014, 2, 6.15);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2024/06/22 14:59:59", 130401, 1, "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", 2, "ナーナ", -470.0, "2024/03/15 15:00:00", 4, 2002, 10015, 2, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2024/06/22 14:59:59", 130401, 2, "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", 2, "ナーナ", -470.0, "2024/03/15 15:00:00", 4, 2002, 10016, 1, 3.35);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2024/09/22 14:59:59", 130502, 1, "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", 1, "ホウオウ", -470.0, "2024/06/15 15:00:00", 5, 2002, 10017, 1, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2024/09/22 14:59:59", 130502, 2, "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", 2, "ホウオウ", -470.0, "2024/06/15 15:00:00", 5, 2002, 10018, 1, 3.18);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2024/09/22 14:59:59", 130503, 3, "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", 4, "ホウオウ", -470.0, "2024/06/15 15:00:00", 5, 2002, 10019, 4, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2024/09/22 14:59:59", 123301, 1, "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", 1, "ネア", -470.0, "2024/06/15 15:00:00", 5, 2002, 10020, 2, 4.9);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2024/09/22 14:59:59", 123301, 2, "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", 1, "ネア", -470.0, "2024/06/15 15:00:00", 5, 2002, 10021, 2, 4.8);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2024/12/22 14:59:59", 133301, 1, "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", 3, "カリザ", -470.0, "2024/09/15 15:00:00", 6, 2002, 10022, 1, 4.922);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2024/12/22 14:59:59", 133301, 2, "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", 3, "カリザ", -470.0, "2024/09/15 15:00:00", 6, 2002, 10023, 5, 9.638);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2024/12/22 14:59:59", 133401, 1, "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", 1, "ミーア", -470.0, "2024/09/15 15:00:00", 6, 2002, 10024, 2, 2.88);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2024/12/22 14:59:59", 133401, 2, "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", 5, "ミーア", -470.0, "2024/09/15 15:00:00", 6, 2002, 10025, 1, 4.818);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2025/03/22 14:59:59", 133002, 1, "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", 2, "グレイス", -470.0, "2024/12/15 15:00:00", 7, 2002, 10026, 1, 1.78);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2025/03/22 14:59:59", 133002, 2, "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", 1, "グレイス", -470.0, "2024/12/15 15:00:00", 7, 2002, 10027, 7, 6.15);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2025/03/22 14:59:59", 133102, 1, "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", 6, "ヴァイオレット", -470.0, "2024/12/15 15:00:00", 7, 2002, 10028, 2, 4.28);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2025/03/22 14:59:59", 133102, 2, "じめじめした商品は\nございませんので\n安心してお買い求め下さい", 1, "ヴァイオレット", -470.0, "2024/12/15 15:00:00", 7, 2002, 10029, 1, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2025/06/23 14:59:59", 136902, 1, "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", 2, "ルルィ", -470.0, "2025/03/15 15:00:00", 8, 2002, 10030, 1, 5.53);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2025/06/23 14:59:59", 136902, 2, "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", 9, "ルルィ", -470.0, "2025/03/15 15:00:00", 8, 2002, 10031, 7, 6.05);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2025/06/23 14:59:59", 137001, 1, "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", 2, "デュラン", -470.0, "2025/03/15 15:00:00", 8, 2002, 10032, 1, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2025/06/23 14:59:59", 137001, 2, "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", 2, "デュラン", -470.0, "2025/03/15 15:00:00", 8, 2002, 10033, 1, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2025/09/23 14:59:59", 135902, 1, "おう\n好きなもん持ってきな", 2, "サツキ", -470.0, "2025/06/16 15:00:00", 9, 2002, 10034, 2, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2025/09/23 14:59:59", 135902, 2, "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", 1, "サツキ", -470.0, "2025/06/16 15:00:00", 9, 2002, 10035, 6, 4.935);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2025/09/23 14:59:59", 135802, 1, "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", 2, "ユキノ", -470.0, "2025/06/16 15:00:00", 9, 2002, 10036, 5, 7.441);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2025/09/23 14:59:59", 135802, 2, "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", 7, "ユキノ", -470.0, "2025/06/16 15:00:00", 9, 2002, 10037, 7, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2025/12/22 14:59:59", 130901, 1, "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", 2, "クルル", -470.0, "2025/09/16 15:00:00", 10, 2002, 10038, 2, 2.295);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2025/12/22 14:59:59", 130901, 2, "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", 1, "クルル", -470.0, "2025/09/16 15:00:00", 10, 2002, 10039, 6, 6.281);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2025/12/22 14:59:59", 137701, 1, "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", 2, "ヴォルガーノ", -470.0, "2025/09/16 15:00:00", 10, 2002, 10040, 1, 5.549);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2025/12/22 14:59:59", 137701, 2, "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", 3, "ヴォルガーノ", -470.0, "2025/09/16 15:00:00", 10, 2002, 10041, 6, 2.64);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2026/03/23 11:59:59", 132801, 1, "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", 7, "ライラエル", -470.0, "2025/12/15 15:00:00", 11, 2002, 10042, 4, 7.642);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2026/03/23 11:59:59", 132802, 2, "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", 1, "ライラエル", -470.0, "2025/12/15 15:00:00", 11, 2002, 10043, 1, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2026/03/23 11:59:59", 134502, 1, "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", 1, "クローチェ", -470.0, "2025/12/15 15:00:00", 11, 2002, 10044, 1, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2026/03/23 11:59:59", 134501, 2, "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", 2, "クローチェ", -470.0, "2025/12/15 15:00:00", 11, 2002, 10045, 1, 3.72);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2026/06/22 11:59:59", 138201, 1, "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", 2, "ネフィ＝ネラ", -470.0, "2026/03/16 12:00:00", 12, 2002, 10046, 1, 4.991);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2026/06/22 11:59:59", 138201, 2, "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", 1, "ネフィ＝ネラ", -470.0, "2026/03/16 12:00:00", 12, 2002, 10047, 4, 3.877);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2026/06/22 11:59:59", 136001, 1, "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", 4, "アラクネ", -470.0, "2026/03/16 12:00:00", 12, 2002, 10048, 6, 1.71);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2026/06/22 11:59:59", 136001, 2, "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", 5, "アラクネ", -470.0, "2026/03/16 12:00:00", 12, 2002, 10049, 2, 5.32);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2026/09/22 11:59:59", 135401, 1, "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", 9, "アネモネ", -470.0, "2026/06/15 12:00:00", 13, 2002, 10050, 4, 3.727);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2026/09/22 11:59:59", 135401, 2, "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", 7, "アネモネ", -470.0, "2026/06/15 12:00:00", 13, 2002, 10051, 9, 7.213);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2026/09/22 11:59:59", 135301, 1, "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", 1, "クリア", -470.0, "2026/06/15 12:00:00", 13, 2002, 10052, 2, 1.874);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2026/09/22 11:59:59", 135301, 2, "アルバイトが終わったら\n海に遊びに行きましょう！\nモネちゃんも一緒に♪", 2, "クリア", -470.0, "2026/06/15 12:00:00", 13, 2002, 10053, 2, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2026/12/22 11:59:59", 138001, 1, "大いなる命、神なる勇魚…\n慈しみの矜持を胸に素敵な\n商品をお売りいたします", 2, "ヴァイオレット", -470.0, "2026/09/15 12:00:00", 14, 2002, 10054, 1, 4.215);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2026/12/22 11:59:59", 138001, 2, "すみません、わたくしの\n手料理は売り切れなのです\nグレイスが、買い占めを…", 4, "ヴァイオレット", -470.0, "2026/09/15 12:00:00", 14, 2002, 10055, 4, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2026/12/22 11:59:59", 138901, 1, "何故かいかがわしいお店と\n勘違いされるんですよね\n騎士氏も？　ヤダへんふし", 6, "グレイス", -470.0, "2026/09/15 12:00:00", 14, 2002, 10056, 1, 5.477);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (0.0, "2026/12/22 11:59:59", 138901, 2, "どうも。グレイスちゃん\n客寄せバージョンですぴょん\n一名様ごあんな～い", 2, "グレイス", -470.0, "2026/09/15 12:00:00", 14, 2002, 10057, 1, 5.743);
